using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
public static class InspectAngelNow {
 public static string Run(){var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/ExpeditionEnemies/AngelKnight.prefab");var a=p.GetComponentInChildren<Animator>();var c=(AnimatorController)a.runtimeAnimatorController;return Newtonsoft.Json.JsonConvert.SerializeObject(new {avatar=a.avatar?a.avatar.name:"null",scale=a.transform.localScale.ToString(),states=c.layers[0].stateMachine.states.Select(x=>new {name=x.state.name,clip=x.state.motion.name,length=((AnimationClip)x.state.motion).length,root=AnimationUtility.GetCurveBindings((AnimationClip)x.state.motion).Where(b=>b.propertyName.Contains("Position")&&(b.path.Split('/').Length<3)).Select(b=>new {b.path,b.propertyName,min=AnimationUtility.GetEditorCurve((AnimationClip)x.state.motion,b).keys.Min(k=>k.value),max=AnimationUtility.GetEditorCurve((AnimationClip)x.state.motion,b).keys.Max(k=>k.value)})})});}
}
